example.q:
执行以下程序后，屏幕输出结果是（ ）。
int f() {
    static int a = 2;
    int b = 1;
    a += 2;
    b += 2;
    return a + b;
}
int main() {
    int r1 = f();
    int r2 = f();
    printf("%d,%d", r1, r2);
    return 0;
}

